window.RP_SESSION={"id":"S-e7f04906bd76","messages":[{"id":"RP-II-0078982","time":"2026-04-10T19:02:00+09:00","room":"RP II","name":"서술자 / 그란벨루크의 목격담","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"이상한 일이다.\n\n참 기묘한 일이다.\n\n골기아의 수도, 갈디고스 동부의 작은 마을 그란벨루크에서 묘한 짐승이 나타났다더라.\n\n두 발로 돌아다니는 몸은 시뻘건게 꼭 핏물을 뒤집어 쓴 것 같고.\n\n팔 다리가 길쭉한 것이 사람과도 닮은 것 같고.\n\n처음 그것을 발견한 것은 소농민인 뤼겔 호퍼스였는데, 뻘건 머리 가운데 큼지막한 둥근 눈이 자신을 쳐다보는게 마치 누군가를 찾는 이의 눈빛 같다고 그랬다.\n\n참 묘한 일이었다.","characters":[]},{"id":"RP-II-0078983","time":"2026-04-10T19:03:00+09:00","room":"RP II","name":"서술자 / 그란벨루크의 목격담","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0078984","time":"2026-04-10T19:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
